// BUSCAR EN FUENTES: baja los avisos de todas las fuentes y los deja en un formato único.
// Para agregar o sacar una fuente, tocá el array FUENTES de abajo.
// Fuentes: Remotive, We Work Remotely, Himalayas, Jobicy y Get on Board (APIs y feeds públicos).
// Revisá los términos de cada sitio (límites de uso y atribución) antes de usarlo.

const DIAS_MAX = 21;      // ignora avisos más viejos que esto
const TOPE = 150;         // máximo de avisos que pasan a la etapa de scoring por corrida

const CONSULTAS_HIMALAYAS = ['revenue operations', 'sales operations', 'business operations', 'hubspot', 'automation specialist', 'chief of staff'];
const CONSULTAS_GETONBRD = ['operations', 'revenue operations', 'sales operations', 'automation'];

const UA = { 'User-Agent': 'Mozilla/5.0 (n8n job-search workflow)' };
// Según la versión de n8n el helper se llama $helpers o helpers
const H = typeof $helpers !== 'undefined' ? $helpers : typeof helpers !== 'undefined' ? helpers : null;
if (!H || !H.httpRequest) throw new Error('Este n8n no expone httpRequest en el nodo Code');
const pedir = (url, opts = {}) => H.httpRequest({ method: 'GET', url, headers: UA, timeout: 30000, ...opts });

const limpiar = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();
const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const clave = (a) => `${norm(a.empresa)}|${norm(a.puesto)}`;
const corte = (s, n) => (s.length > n ? s.slice(0, n) + ' [...]' : s);

function itemsRSS(xml) {
  const out = [];
  const re = /<item>([\s\S]*?)<\/item>/g;
  let m;
  while ((m = re.exec(xml))) {
    const b = m[1];
    const campo = (t) => {
      const r = new RegExp(`<${t}>([\\s\\S]*?)</${t}>`).exec(b);
      if (!r) return '';
      return limpiar(r[1].replace(/<!\[CDATA\[|\]\]>/g, ''));
    };
    out.push({ title: campo('title'), link: campo('link'), pubDate: campo('pubDate'), region: campo('region'), country: campo('country'), type: campo('type'), description: campo('description') });
  }
  return out;
}

const FUENTES = [
  {
    nombre: 'Remotive',
    async traer() {
      // La API gratis devuelve como máximo 15 avisos y pide no llamarla más de 4 veces por día
      const r = await pedir('https://remotive.com/api/remote-jobs?limit=100');
      return (r.jobs || []).map((j) => ({
        empresa: j.company_name,
        puesto: j.title,
        link: j.url,
        region: j.candidate_required_location || '',
        publicado: j.publication_date || '',
        salario_txt: j.salary || '',
        contrato_txt: j.job_type || '',
        desc: limpiar(j.description),
      }));
    },
  },
  {
    nombre: 'WeWorkRemotely',
    async traer() {
      const feeds = [
        'https://weworkremotely.com/categories/remote-sales-and-marketing-jobs.rss',
        'https://weworkremotely.com/categories/remote-management-and-finance-jobs.rss',
        'https://weworkremotely.com/categories/all-other-remote-jobs.rss',
      ];
      const out = [];
      for (const f of feeds) {
        const xml = await pedir(f);
        for (const it of itemsRSS(String(xml))) {
          const partes = it.title.split(':');
          const empresa = partes.length > 1 ? partes[0].trim() : '';
          const puesto = partes.length > 1 ? partes.slice(1).join(':').trim() : it.title;
          out.push({ empresa, puesto, link: it.link, region: [it.region, it.country].filter(Boolean).join(', '), publicado: it.pubDate, salario_txt: '', contrato_txt: it.type, desc: it.description });
        }
      }
      return out;
    },
  },
  {
    nombre: 'Himalayas',
    async traer() {
      const out = [];
      for (const q of CONSULTAS_HIMALAYAS) {
        const r = await pedir(`https://himalayas.app/jobs/api/search?q=${encodeURIComponent(q)}`);
        for (const j of r.jobs || []) {
          const salario = j.minSalary || j.maxSalary ? `${j.minSalary || ''}-${j.maxSalary || ''} ${j.currency || ''} ${j.salaryPeriod || ''}` : '';
          out.push({
            empresa: j.companyName,
            puesto: j.title,
            link: j.applicationLink || `https://himalayas.app/companies/${j.companySlug}/jobs`,
            region: (j.locationRestrictions || []).join(', '),
            publicado: j.pubDate ? new Date(j.pubDate * 1000 || j.pubDate).toISOString() : '',
            salario_txt: salario,
            contrato_txt: [j.employmentType, (j.seniority || []).join('/')].filter(Boolean).join(' '),
            desc: limpiar(j.description || j.excerpt),
          });
        }
      }
      return out;
    },
  },
  {
    nombre: 'Jobicy',
    async traer() {
      const r = await pedir('https://jobicy.com/api/v2/remote-jobs?count=50&geo=latam');
      return (r.jobs || []).map((j) => ({
        empresa: j.companyName,
        puesto: j.jobTitle,
        link: j.url,
        region: Array.isArray(j.jobGeo) ? j.jobGeo.join(', ') : j.jobGeo || '',
        publicado: j.pubDate || '',
        salario_txt: j.annualSalaryMin ? `${j.annualSalaryMin}-${j.annualSalaryMax || ''} ${j.salaryCurrency || 'USD'} anual` : '',
        contrato_txt: [].concat(j.jobType || [], j.jobLevel || []).join(' '),
        desc: limpiar(j.jobDescription || j.jobExcerpt),
      }));
    },
  },
  {
    nombre: 'GetOnBoard',
    async traer() {
      const out = [];
      for (const q of CONSULTAS_GETONBRD) {
        const r = await pedir(`https://www.getonbrd.com/api/v0/search/jobs?query=${encodeURIComponent(q)}&per_page=25&expand=${encodeURIComponent('["company"]')}`);
        for (const j of r.data || []) {
          const a = j.attributes || {};
          if (a.remote === false) continue; // presencial o híbrido, no sirve
          out.push({
            empresa: (a.company && a.company.data && a.company.data.attributes && a.company.data.attributes.name) || 'Get on Board',
            puesto: a.title,
            link: (j.links && j.links.public_url) || `https://www.getonbrd.com/jobs/${j.id}`,
            region: `Latin America ${a.remote_zone || ''} ${(a.countries || []).join(', ')}`.trim(),
            publicado: a.published_at ? new Date(a.published_at * 1000).toISOString() : '',
            salario_txt: a.min_salary ? `${a.min_salary}-${a.max_salary || ''} USD mensual` : '',
            contrato_txt: a.modality || '',
            desc: limpiar(`${a.description_headline || ''} ${a.description || ''} ${a.functions || ''}`),
          });
        }
      }
      return out;
    },
  },
];

const diag = { por_fuente: {}, errores: [] };
const crudos = [];

for (const f of FUENTES) {
  try {
    const avisos = await f.traer();
    diag.por_fuente[f.nombre] = avisos.length;
    if (!avisos.length) diag.errores.push(`${f.nombre}: no devolvió avisos`);
    for (const a of avisos) crudos.push({ ...a, fuente: f.nombre });
  } catch (e) {
    diag.por_fuente[f.nombre] = 0;
    diag.errores.push(`${f.nombre}: ${String(e.message || e).slice(0, 120)}`);
  }
}

// Filtra viejos, deduplica dentro de la misma corrida y ordena por fecha
const limite = Date.now() - DIAS_MAX * 24 * 60 * 60 * 1000;
const vistas = new Set();
const salida = [];

for (const a of crudos) {
  if (!a.puesto || !a.link) continue;
  const ts = Date.parse(a.publicado) || 0;
  if (ts && ts < limite) continue;
  const k = clave(a);
  if (vistas.has(k)) continue;
  vistas.add(k);
  salida.push({
    json: {
      clave: k,
      empresa: a.empresa || '(sin empresa)',
      puesto: a.puesto,
      link: a.link,
      region: a.region || '',
      publicado: a.publicado || '',
      publicado_ts: ts,
      salario_txt: a.salario_txt || '',
      contrato_txt: a.contrato_txt || '',
      desc: corte(String(a.desc || ''), 2500),
      fuente: a.fuente,
    },
  });
}

salida.sort((x, y) => (y.json.publicado_ts || 0) - (x.json.publicado_ts || 0));

const sd = $getWorkflowStaticData('global');
sd.diag = { ...diag, total: crudos.length, unicos: salida.length, fecha: new Date().toISOString() };

return salida.slice(0, TOPE * 3); // el tope final se aplica después de deduplicar contra el Sheet

// FILTRAR Y DEDUPLICAR: saca lo que ya viste y aplica los descartes por regla (sin IA).
// Acá se ajusta qué regiones y qué rubros valen la pena.

const TOPE_IA = 120; // máximo de avisos que se mandan a Ollama por corrida

const LATAM = /(latam|latin america|south america|américa latina|america latina|americas|argentina|brasil|brazil|mexico|méxico|colombia|chile|per[uú]|uruguay|paraguay|bolivia|ecuador|costa rica|guatemala|panam[aá]|rep[uú]blica dominicana)/i;
const ABIERTO = /(anywhere|worldwide|global|remote, any|any location|sin restricci)/i;

const RUBRO_EXCLUIDO = /(designer|design lead|ux\b|ui\/ux|graphic|illustrator|animator|3d |video editor|\beditor\b|copywriter|content writer|proofreader|technical author|seo\b|paid media|ppc|media buyer|performance marketing|salesforce (admin|developer)|software engineer|developer|backend|front.?end|full.?stack|devops|\bsre\b|site reliability|infrastructure|kubernetes|containeriz|virtualis|microservices|security engineer|cloud engineer|field engineer|solution(s)? architect|architecture manager|engineering manager|data engineer|machine learning|ml engineer|qa engineer|\bcad\b|drafter|nurse|\brn\b|medical|construction|attorney|paralegal|architect\b|electrician|driver|teacher)/i;
// Títulos que igual valen aunque tengan una palabra de la lista de arriba
const RUBRO_RESCATE = /(revenue operations|revops|sales ops|business operations|automation|crm|hubspot|ai agent|workflow)/i;
const SOLO_COMISION = /(commission[- ]only|100% commission|comisi[oó]n pura|solo comisi[oó]n|uncapped commission only)/i;
// Puestos que exigen estar o ser de EE.UU. aunque el aviso figure como remoto
const SOLO_EEUU = /(security clearance|us citizen|u\.s\. citizen|citizenship required|must reside in the (us|united states)|based in the united states|w-2 only|federal government|public trust clearance)/i;

// Si el aviso dice dónde tenés que estar y no incluye LATAM ni "anywhere", se descarta.
// Si no dice nada, pasa igual y lo decide el score.
function regionOk(texto) {
  const t = String(texto || '');
  if (!t.trim()) return 'desconocida';
  if (LATAM.test(t) || ABIERTO.test(t)) return 'ok';
  return 'no';
}

// Claves que ya pasaron por acá en corridas anteriores
const yaVistas = new Set(
  $('Leer vistos').all()
    .map((it) => String(it.json.clave || '').trim())
    .filter(Boolean)
);

const nuevos = [];

for (const it of $input.all()) {
  const j = it.json;
  if (yaVistas.has(j.clave)) continue;

  const texto = `${j.puesto} ${j.desc}`;
  let resultado = 'ok';
  let motivo_descarte = '';

  const reg = regionOk(j.region);
  if (reg === 'no') {
    resultado = 'descartado_region';
    motivo_descarte = `Región: ${j.region}`;
  } else if (RUBRO_EXCLUIDO.test(j.puesto) && !RUBRO_RESCATE.test(j.puesto)) {
    resultado = 'descartado_rubro';
    motivo_descarte = 'Rubro fuera de tu búsqueda';
  } else if (SOLO_COMISION.test(texto)) {
    resultado = 'descartado_comision';
    motivo_descarte = 'Solo comisión';
  } else if (SOLO_EEUU.test(texto)) {
    resultado = 'descartado_region';
    motivo_descarte = 'Pide ciudadanía o residencia en EE.UU.';
  }

  nuevos.push({ json: { ...j, resultado, motivo_descarte, region_check: reg } });
}

// Los que van a Ollama: primero los más nuevos, con tope
let paraIA = 0;
for (const n of nuevos) {
  if (n.json.resultado !== 'ok') continue;
  paraIA += 1;
  if (paraIA > TOPE_IA) {
    n.json.resultado = 'pendiente_proxima_corrida';
    n.json.motivo_descarte = 'Tope de la corrida, se evalúa mañana';
  }
}

const sd = $getWorkflowStaticData('global');
sd.diag = { ...(sd.diag || {}), nuevos: nuevos.length, a_ia: Math.min(paraIA, TOPE_IA) };

return nuevos;

// ARMAR PROMPT EMPLEO: el modelo solo extrae datos del aviso. Los descartes y el score los decide el nodo Puntuar.

const MODELO = 'qwen2.5:7b';

const PERFIL = `La persona busca trabajo remoto (contractor o empleado) cobrando en USD y vive en América Latina. Es especialista en Revenue Operations y automatización: administra HubSpot y otros CRM, construye automatizaciones en n8n, Zapier y Make, enriquece leads y arma reportes de pipeline. Inglés fluido. EDITÁ ESTE TEXTO con tu propio perfil.`;

const SYSTEM = `Leés un aviso de trabajo y devolvés SOLO JSON con datos extraídos del aviso. No opinás ni puntuás.

PERFIL DE QUIEN BUSCA:
${PERFIL}

"familia_rol": la que mejor describe el puesto.
- "revops_salesops_bizops": Revenue Ops, Sales Ops, Business Ops, Operations Manager o Analyst.
- "hubspot_crm_admin": administrar, implementar o configurar un CRM (HubSpot, CRM admin, CRM manager).
- "automation_ai": Automation Specialist, AI Automation, workflow o process automation, n8n/Zapier/Make, agentes de IA.
- "marketing_ops": Marketing Operations, lifecycle, email ops.
- "chief_of_staff_ea": Chief of Staff, Executive Assistant, asistente de founder.
- "customer_success_account": Customer Success, Account Manager, Client Ops.
- "sdr_bdr_ventas": SDR, BDR, Account Executive, ventas.
- "project_coordinator": Project Manager o Coordinator, PMO.
- "otro": cualquier otra cosa.

"anios_requeridos": años de experiencia que pide el aviso, como número. null si no lo dice. Nunca pongas 0. Si dice un rango, usá el mínimo.

"requiere_documentos_us": true solo si el aviso exige autorización para trabajar en EE.UU., ciudadanía o residencia estadounidense, green card, visa, security clearance, estar físicamente en EE.UU. o cobrar como W-2. false si no lo pide o si no dice nada.

"paises_permitidos": lista de países o regiones que el aviso permite de forma explícita, como los escribe el aviso (ej: ["Brazil","Peru"], ["LATAM"], ["Anywhere"]). Lista vacía si el aviso no aclara desde dónde se puede trabajar.

"herramientas": hasta 6 herramientas o plataformas que el aviso nombra de forma literal, en minúscula. [] si no nombra ninguna. Nunca inventes.

"pago_usd_mes": pago mensual en dólares. Si el aviso da un rango, el promedio. Si es anual, dividido por 12. Si es por hora, por 160. null si no dice.

"contrato": "contractor" solo si el aviso dice contractor, freelance, 1099 o B2B. "empleado" si habla de relación de dependencia o beneficios. "no_dice" si no aclara.

"motivo": una oración en español, máximo 20 palabras: qué es el puesto y qué pide.`;

const SCHEMA = {
  type: 'object',
  properties: {
    familia_rol: { type: 'string', enum: ['revops_salesops_bizops', 'hubspot_crm_admin', 'automation_ai', 'marketing_ops', 'chief_of_staff_ea', 'customer_success_account', 'sdr_bdr_ventas', 'project_coordinator', 'otro'] },
    anios_requeridos: { type: ['integer', 'null'] },
    requiere_documentos_us: { type: 'boolean' },
    paises_permitidos: { type: 'array', items: { type: 'string' } },
    herramientas: { type: 'array', items: { type: 'string' } },
    pago_usd_mes: { type: ['number', 'null'] },
    contrato: { type: 'string', enum: ['contractor', 'empleado', 'no_dice'] },
    motivo: { type: 'string' },
  },
  required: ['familia_rol', 'anios_requeridos', 'requiere_documentos_us', 'paises_permitidos', 'herramientas', 'pago_usd_mes', 'contrato', 'motivo'],
};

return $input.all().map((item, i) => {
  const j = item.json;
  const user = `Puesto: ${j.puesto}
Empresa: ${j.empresa}
Región que figura en el portal: ${j.region || 'no dice'}
Tipo de contrato que figura: ${j.contrato_txt || 'no dice'}
Sueldo que figura: ${j.salario_txt || 'no dice'}
Descripción:
${j.desc || '(el aviso no trae descripción)'}`;

  return {
    json: {
      ...j,
      ollama_request: {
        model: MODELO,
        stream: false,
        format: SCHEMA,
        keep_alive: '15m',
        options: { temperature: 0, num_ctx: 4096 },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: user },
        ],
      },
    },
    pairedItem: { item: i },
  };
});

// PUNTUAR: descarta con reglas duras lo que no te sirve y puntúa el resto.
// Todo lo configurable está en este bloque de arriba.

const MAX_ANIOS = 3;            // se descarta el aviso que pida MÁS de estos años (ejemplo: 4 o más, fuera)
const PAGO_MIN = 1500;          // USD por mes (ejemplo)
const FAMILIA_OBJETIVO = ['revops_salesops_bizops', 'hubspot_crm_admin', 'automation_ai'];
const FAMILIA_SECUNDARIA = ['customer_success_account', 'sdr_bdr_ventas'];
// Lo que no esté en esas dos listas se descarta por rubro (marketing ops, chief of staff, PM, otro)

const MIS_HERRAMIENTAS = ['hubspot', 'clay', 'apollo', 'sales navigator', 'n8n', 'zapier', 'make', 'power bi', 'excel', 'google sheets', 'google analytics', 'notion', 'asana', 'clickup', 'webhook', 'rest api', 'openai', 'claude', 'gpt', 'ocr'];
const DIFERENCIALES = ['hubspot', 'n8n']; // suman un punto extra

const NOMBRE_FAMILIA = {
  revops_salesops_bizops: 'RevOps / Sales Ops / BizOps',
  hubspot_crm_admin: 'HubSpot / CRM admin',
  automation_ai: 'Automatización / IA',
  marketing_ops: 'Marketing Ops',
  chief_of_staff_ea: 'Chief of Staff / EA',
  customer_success_account: 'Customer Success / Account',
  sdr_bdr_ventas: 'Ventas / SDR',
  project_coordinator: 'Project Coordinator',
  otro: 'Otro',
};

// Países o regiones desde donde se puede trabajar (editá según tu caso)
const PAIS_OK = /(argentina|latam|latin america|south america|américa latina|america latina|americas|anywhere|worldwide|global)/i;
// Redes de seguridad por si el modelo no marca el campo
const RE_DOCS_US = /(authorized to work in the (us|u\.s\.|united states)|work authorization|us work authorization|must be (a )?(us|u\.s\.) (citizen|resident)|green card|security clearance|w-?2 (only|employee)|eligible to work in the united states|visa sponsorship is not)/i;
const RE_VENTAS = /\b(sdr|bdr|account executive|business development (rep|representative|associate)|sales (rep|representative|associate)|inside sales|client development|client partner)\b/i;
const RE_CS = /(customer success|account manager|customer support|client services)/i;
const RE_CONTRACTOR = /(contractor|freelance|1099|\bb2b\b|independent contractor|contrato de servicios)/i;

function leerJSON(j) {
  const raw = (j && ((j.message && j.message.content) || j.output || j.text || j.response)) || '';
  const txt = String(raw).replace(/```(?:json)?/gi, '');
  const ini = txt.indexOf('{');
  const fin = txt.lastIndexOf('}');
  if (ini < 0 || fin <= ini) throw new Error('sin JSON');
  return JSON.parse(txt.slice(ini, fin + 1));
}

const base = $('Armar prompt empleo').all();
const hoy = new Date().toLocaleDateString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', day: '2-digit', month: '2-digit', year: 'numeric' });
const conteo = {};

const salida = $input.all().map((r, i) => {
  // Empareja por pairedItem (no por posición); si el linaje se pierde, cae al índice
  const j = (() => { try { return $('Armar prompt empleo').itemMatching(i).json; } catch (e) { return base[i].json; } })();
  let p = null;
  let falloIA = false;

  try {
    p = leerJSON(r.json);
  } catch (e) {
    p = { familia_rol: 'otro', anios_requeridos: null, requiere_documentos_us: false, paises_permitidos: [], herramientas: [], pago_usd_mes: null, contrato: 'no_dice', motivo: '(Ollama no respondió, revisalo a mano)' };
    falloIA = true;
  }

  const texto = `${j.puesto} ${j.desc}`.toLowerCase();

  // Correcciones sobre lo que extrajo el modelo
  if (RE_VENTAS.test(j.puesto)) p.familia_rol = 'sdr_bdr_ventas';
  else if (RE_CS.test(j.puesto)) p.familia_rol = 'customer_success_account';
  p.herramientas = (Array.isArray(p.herramientas) ? p.herramientas : []).filter((h) => texto.includes(String(h).toLowerCase()));
  if (p.contrato === 'contractor' && !RE_CONTRACTOR.test(texto)) p.contrato = 'no_dice';
  if (p.anios_requeridos === 0) p.anios_requeridos = null;
  if (Number.isFinite(p.pago_usd_mes) && p.pago_usd_mes < 500) p.pago_usd_mes = null;
  if (RE_DOCS_US.test(texto)) p.requiere_documentos_us = true;

  const anios = Number.isFinite(p.anios_requeridos) ? p.anios_requeridos : null;
  // "Remote" a secas no es un país: se ignora, así "Remote (US only)" no se cuela
  const paises = (Array.isArray(p.paises_permitidos) ? p.paises_permitidos.filter(Boolean) : [])
    .filter((c) => !/^(remote|remoto|fully remote|100% remote|work from home)$/i.test(String(c).trim()));

  // Descartes duros, en orden
  let resultado = 'ok';
  let motivo_descarte = '';

  if (falloIA) {
    resultado = 'sin_evaluar';
    motivo_descarte = 'Ollama no respondió';
  } else if (p.requiere_documentos_us) {
    resultado = 'descartado_documentos_us';
    motivo_descarte = 'Pide papeles para trabajar en EE.UU.';
  } else if (paises.length && !paises.some((c) => PAIS_OK.test(c))) {
    resultado = 'descartado_pais';
    motivo_descarte = `Solo acepta: ${paises.slice(0, 4).join(', ')}`;
  } else if (anios !== null && anios > MAX_ANIOS) {
    resultado = 'descartado_anios';
    motivo_descarte = `Pide ${anios} años`;
  } else if (!FAMILIA_OBJETIVO.includes(p.familia_rol) && !FAMILIA_SECUNDARIA.includes(p.familia_rol)) {
    resultado = 'descartado_rubro';
    motivo_descarte = `Rol fuera de tu búsqueda: ${NOMBRE_FAMILIA[p.familia_rol] || p.familia_rol}`;
  }

  conteo[resultado] = (conteo[resultado] || 0) + 1;

  // Score, solo para los que pasaron
  const razones = [];
  let score = 0;
  let tipo_rol = 'descartado';

  if (resultado === 'ok') {
    if (FAMILIA_OBJETIVO.includes(p.familia_rol)) { score += 4; tipo_rol = 'objetivo'; razones.push('rol objetivo'); }
    else { score += 2; tipo_rol = 'secundario'; razones.push('rol secundario'); }

    if (anios === null) { score += 1; razones.push('no dice años'); }
    else { score += 2; razones.push(`pide ${anios} años`); }

    const match = p.herramientas.filter((h) => MIS_HERRAMIENTAS.some((m) => h.includes(m)));
    if (match.length) { score += Math.min(2, match.length); razones.push(`usa ${match.slice(0, 3).join(', ')}`); }
    if (DIFERENCIALES.some((d) => texto.includes(d))) { score += 1; razones.push('nombra HubSpot o n8n'); }

    const pago = Number.isFinite(p.pago_usd_mes) ? Math.round(p.pago_usd_mes) : null;
    if (pago === null) { score += 1; razones.push('no publica sueldo'); }
    else if (pago >= PAGO_MIN) { score += 2; razones.push(`USD ${pago}/mes`); }
    else razones.push(`USD ${pago}/mes, bajo`);

    if (p.contrato === 'contractor') { score += 1; razones.push('contractor'); }
    score = Math.min(10, score);
  } else {
    razones.push(motivo_descarte);
  }

  const herramientasTxt = p.herramientas.filter((h) => MIS_HERRAMIENTAS.some((m) => h.includes(m))).join(', ');

  return {
    json: {
      fecha_detectado: hoy,
      score,
      empresa: j.empresa,
      puesto: j.puesto,
      tipo_rol: resultado === 'ok' ? `${tipo_rol} (${NOMBRE_FAMILIA[p.familia_rol]})` : resultado,
      region: paises.length ? paises.join(', ') : j.region || 'no dice',
      experiencia_anios: anios === null ? '' : anios,
      pago_usd_mes: Number.isFinite(p.pago_usd_mes) ? Math.round(p.pago_usd_mes) : '',
      contrato: p.contrato,
      herramientas_match: herramientasTxt,
      motivo: `${razones.join(', ')}. ${String(p.motivo || '').trim()}`.slice(0, 300),
      fuente: j.fuente,
      link: j.link,
      publicado: j.publicado || '',
      clave: j.clave,
      estado: 'nuevo',
      resultado,
    },
    pairedItem: { item: i },
  };
});

const sd = $getWorkflowStaticData('global');
sd.diag = { ...(sd.diag || {}), post_ia: conteo };

return salida;

// ARMAR VISTOS: una fila por cada aviso nuevo de hoy, tanto los que entran al pipeline como los descartados.
// Es la memoria del workflow y la fuente de los números para tu case study.

const hoy = new Date().toLocaleDateString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', day: '2-digit', month: '2-digit', year: 'numeric' });

const puntuados = new Map();
for (const it of $input.all()) puntuados.set(it.json.clave, it.json);

// Los que quedaron fuera por el tope del día NO se guardan: así mañana se evalúan.
return $('Filtrar y deduplicar').all()
  .filter((it) => it.json.resultado !== 'pendiente_proxima_corrida')
  .map((it, i) => {
  const j = it.json;
  const p = puntuados.get(j.clave);
  let resultado = j.resultado;
  let score = '';

  if (p) {
    score = p.score;
    // Si Puntuar lo descartó, ese es el resultado; si no, depende del score
    resultado = p.resultado !== 'ok' ? p.resultado : p.score >= 6 ? 'pipeline' : 'score_bajo';
  }

  // Si el modelo no pudo leer el aviso, no se recuerda: se vuelve a evaluar mañana.
  if (resultado === 'sin_evaluar') return null;
  return { json: { clave: j.clave, fecha: hoy, fuente: j.fuente, resultado, score }, pairedItem: { item: i } };
}).filter(Boolean);

// DIGEST: top 10 del día para Telegram, más los números de la corrida y el aviso si una fuente se rompió.

const TOP = 10;
const MINIMO = 6;
const LIMITE_TELEGRAM = 3900;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sd = $getWorkflowStaticData('global');
const diag = sd.diag || {};

const items = $input.all().map((it) => it.json);
const buenos = items.filter((j) => j.resultado === 'ok' && Number(j.score) >= MINIMO).sort((a, b) => b.score - a.score);
const hoy = new Date().toLocaleDateString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', day: '2-digit', month: '2-digit' });

const porFuente = Object.entries(diag.por_fuente || {}).map(([k, v]) => `${k} ${v}`).join(' · ');

const ETIQUETA_DESCARTE = {
  descartado_anios: 'piden más años de los que tenés',
  descartado_documentos_us: 'piden papeles de EE.UU.',
  descartado_pais: 'no aceptan Argentina',
  descartado_rubro: 'rol fuera de tu búsqueda',
  sin_evaluar: 'Ollama no respondió',
};
const postIA = diag.post_ia || {};
const descartes = Object.entries(postIA)
  .filter(([k]) => k !== 'ok')
  .map(([k, v]) => `${v} ${ETIQUETA_DESCARTE[k] || k}`)
  .join(' · ');

let msg = `<b>Búsqueda laboral · ${hoy}</b>\nAvisos bajados: ${diag.total || 0} · Nuevos: ${diag.nuevos || 0} · Evaluados: ${items.length} · Al pipeline: ${buenos.length}`;

if ((diag.errores || []).length) {
  msg += `\n\n<b>Ojo:</b> ${esc(diag.errores.join(' | '))}`;
}

if (descartes) msg += `\nDescartados al leerlos: ${descartes}`;

if (!buenos.length) {
  // Muestra igual lo mejor del día, así se ve si fue por las reglas o porque el modelo falló
  const fallaronIA = items.filter((j) => /Ollama no respondió/i.test(j.motivo || '')).length;
  msg += `\n\nHoy no salió nada con score ${MINIMO} o más.`;
  if (fallaronIA) msg += `\n<b>${fallaronIA} de ${items.length} fallaron en Ollama.</b> Revisá que el modelo esté levantado.`;
  const mejores = items.sort((a, b) => b.score - a.score).slice(0, 3);
  if (mejores.length) {
    msg += '\n\n<b>Lo mejor que salió igual:</b>';
    for (const j of mejores) {
      const linea = `\n\n<b>${j.score}/10 · ${esc(j.puesto)}</b>\n${esc(j.empresa)} · ${esc(j.region)} · ${esc(j.fuente)}\n${esc(j.motivo)}\n<a href="${esc(j.link)}">ver aviso</a>`;
      if ((msg + linea).length > LIMITE_TELEGRAM) break;
      msg += linea;
    }
  }
} else {
  for (const j of buenos.slice(0, TOP)) {
    const datos = [
      j.experiencia_anios !== '' ? `${j.experiencia_anios} años` : null,
      j.pago_usd_mes !== '' ? `USD ${j.pago_usd_mes}/mes` : null,
      j.region,
      j.fuente,
    ].filter(Boolean).join(' · ');
    const linea = `\n\n<b>${j.score}/10 · ${esc(j.puesto)}</b>\n${esc(j.empresa)} · ${esc(datos)}\n${esc(j.motivo)}\n<a href="${esc(j.link)}">ver aviso</a>`;
    if ((msg + linea).length > LIMITE_TELEGRAM) break;
    msg += linea;
  }
  if (buenos.length > TOP) msg += `\n\nY ${buenos.length - TOP} más en la planilla.`;
}

msg += `\n\n<i>${esc(porFuente)}</i>`;

sd.digest_fecha = DateTime.now().setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd');

return [{ json: { mensaje: msg } }];

// HEARTBEAT: si hoy no salió el digest, avisa por qué. Si ya salió, no dice nada.
// Cubre tres casos: el workflow no corrió, todas las fuentes fallaron, o no hubo avisos nuevos.
// Nota: los datos de ejecución se guardan solo en corridas de producción (workflow activo).
const sd = $getWorkflowStaticData('global');
const TZ = 'America/Argentina/Buenos_Aires';
const hoy = DateTime.now().setZone(TZ).toFormat('yyyy-MM-dd');

if (sd.digest_fecha === hoy) return [];

const diag = sd.diag || {};
const corrioHoy = diag.fecha && DateTime.fromISO(diag.fecha).setZone(TZ).toFormat('yyyy-MM-dd') === hoy;
const errores = diag.errores || [];

let mensaje;
if (!corrioHoy) {
  mensaje = '⚠️ Búsqueda laboral: la corrida de las 8:00 no se ejecutó hoy. Revisá que el workflow esté activo y n8n levantado.';
} else {
  mensaje = 'ℹ️ Búsqueda laboral: hoy no hay nada para revisar. Bajados ' + (diag.total || 0) + ', nuevos ' + (diag.nuevos || 0) + '.';
  if (errores.length) mensaje += ' Problemas en fuentes: ' + errores.join(' | ');
}

return [{ json: { mensaje } }];
